 public sealed class ServingArmIsolationTests {
  const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static readonly string Run=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff");static Type Sports(string n)=>Type.GetType("LWS.TruckSports."+n+", Assembly-CSharp",true);static object Get(object x,string n)=>x.GetType().GetField(n,Any) is FieldInfo f?f.GetValue(x):x.GetType().GetProperty(n,Any).GetValue(x);static void Set(object x,string n,object v)=>x.GetType().GetField(n,Any).SetValue(x,v);static object Call(object x,string n,params object[]a)=>x.GetType().GetMethods(Any).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||(p.ParameterType.IsByRef?p.ParameterType.GetElementType():p.ParameterType).IsInstanceOfType(a[i])).All(v=>v)).Invoke(x,a);static Rigidbody Body(object x)=>(Rigidbody)Get(x,"body");static object Registry(string n,params object[]a)=>Sports("SportsParticipantRegistry").GetMethod(n).Invoke(null,a);
  sealed class Fixture:IDisposable {
   readonly IDisposable prefs;readonly GameObject isolation;readonly InputSettings prior,focus;readonly List<Gamepad> pads=new List<Gamepad>();readonly Gamepad previous;public Behaviour match;public object rules;public object[] arms,trucks,cups,pots;public float[] masses;float nextTrace;readonly System.Text.StringBuilder trace=new System.Text.StringBuilder(30000);string path;
   public Fixture(){prefs=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"TeaNative"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");prior=InputSystem.settings;previous=Gamepad.current;focus=UnityEngine.Object.Instantiate(prior);focus.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;focus.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;focus.updateMode=InputSettings.UpdateMode.ProcessEventsInDynamicUpdate;InputSystem.settings=focus;isolation=new GameObject("Tea fixture physical input isolation");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));}
