   public IEnumerator Load(){Assert.That(File.Exists("Assets/TruckTeaParty/Scenes/TruckTeaParty.unity"),Is.True,"Lead must run the explicit NEW garden author first.");EditorSceneManager.LoadSceneInPlayMode("Assets/TruckTeaParty/Scenes/TruckTeaParty.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=UnityEngine.Object.FindObjectsByType(Type.GetType("LWS.TruckTeaParty.TeaMatch, Assembly-CSharp",true),FindObjectsSortMode.None).Cast<Behaviour>().Single();rules=Get(match,"rules");arms=((Array)Get(match,"arms")).Cast<object>().ToArray();trucks=arms.Select(a=>Get(a,"truck")).ToArray();cups=((Array)Get(match,"cups")).Cast<object>().ToArray();pots=((Array)Get(match,"pots")).Cast<object>().ToArray();masses=trucks.Select(Body).Select(b=>b.mass).ToArray();Assert.That(trucks.Length,Is.EqualTo(4));Assert.That(cups.Length,Is.EqualTo(12));Assert.That(pots.Length,Is.EqualTo(8));Assert.That(trucks.All(t=>Get(t,"tractorMotor")!=null&&Get(t,"appearanceHost")!=null),Is.True);string dir="Logs/TruckSports/PlaytestRepair/TeaPartyControlledNative/"+Run;Directory.CreateDirectory(dir);path=Path.Combine(dir,"physical-"+Guid.NewGuid().ToString("N")+".txt");}
