  [UnityTest,Timeout(60000)]public IEnumerator OriginalTeaTruckAssemblyIgnoresOnlyItsOwnActuatedEquipmentWithoutSelfLaunch(){using(var f=new Fixture()){yield return f.Load();var arm=f.arms[0];var truck=f.trucks[0];var gear=(Transform)Get(arm,"gear");var root=(Component)truck;var equipment=gear.GetComponentsInChildren<Collider>(true).Where(c=>!c.isTrigger).ToArray();var hull=root.GetComponentsInChildren<Collider>(true).Where(c=>!c.transform.IsChildOf(gear)).ToArray();Assert.That(equipment.Length,Is.GreaterThan(0));Assert.That(hull.Any(c=>c.attachedRigidbody!=null&&c.attachedRigidbody!=Body(truck)),Is.True,"The original separate Cab body is part of the same isolation boundary.");Physics.SyncTransforms();int penetrations=0;float deepest=0;foreach(var a in equipment)foreach(var b in hull){if(!a.enabled||!b.enabled||!a.gameObject.activeInHierarchy||!b.gameObject.activeInHierarchy)continue;if(Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out var direction,out float depth)){penetrations++;deepest=Mathf.Max(deepest,depth);TestContext.WriteLine("SERVING_OWN_OVERLAP "+a.name+" -> "+b.name+" depth="+depth.ToString("R")+" direction="+direction.ToString("F6"));}}Assert.That(penetrations,Is.GreaterThan(0),"The saved original shoulder attachment intersects its own physical hull; isolation is necessary, not a route workaround.");var floor=GameObject.Find("Finished English garden lawn").GetComponent<Collider>();var other=((Component)f.trucks[1]).GetComponentsInChildren<Collider>(true).First(c=>!c.isTrigger&&!c.transform.IsChildOf((Transform)Get(f.arms[1],"gear")));var worldBefore=equipment.Select(c=>Physics.GetIgnoreCollision(c,floor)).ToArray();var otherBefore=equipment.Select(c=>Physics.GetIgnoreCollision(c,other)).ToArray();var gravity=Physics.gravity;var simulation=Physics.simulationMode;var matrix=new bool[32,32];for(int a=0;a<32;a++)for(int b=0;b<32;b++)matrix[a,b]=Physics.GetIgnoreLayerCollision(a,b);f.Start();Assert.That((int)Get(arm,"IsolatedOwnPairs"),Is.GreaterThan(0));foreach(var a in equipment)foreach(var b in hull)Assert.That(Physics.GetIgnoreCollision(a,b),Is.True);for(int i=0;i<equipment.Length;i++){Assert.That(Physics.GetIgnoreCollision(equipment[i],floor),Is.EqualTo(worldBefore[i]));Assert.That(Physics.GetIgnoreCollision(equipment[i],other),Is.EqualTo(otherBefore[i]));}var starts=f.trucks.Select(Body).Select(b=>b.position).ToArray();bool acquired=false;float maxHeight=0,maxSpeed=0;Time.timeScale=2;float end=Time.realtimeSinceStartup+18;while((float)Get(f.rules,"Clock")<20&&Time.realtimeSinceStartup<end){f.Observe();acquired|=f.arms.Any(a=>Get(a,"Held")!=null);for(int i=0;i<4;i++){var body=Body(f.trucks[i]);maxHeight=Mathf.Max(maxHeight,body.position.y);maxSpeed=Mathf.Max(maxSpeed,body.linearVelocity.magnitude);Assert.That(body.position.y,Is.LessThan(4),"An unposed original NWH truck must not be launched by its own kinematic equipment.");Assert.That(body.linearVelocity.magnitude,Is.LessThan(30));}yield return null;}TestContext.WriteLine("SERVING_ISOLATION_NATIVE geometricOverlaps="+penetrations+" maxDepth="+deepest.ToString("R")+" maxTruckY="+maxHeight.ToString("R")+" maxSpeed="+maxSpeed.ToString("R")+" nativeAcquired="+acquired);Assert.That(f.trucks.Select((t,i)=>Vector3.Distance(starts[i],Body(t).position)).Max(),Is.GreaterThan(1));Assert.That(acquired,Is.True,"After eliminating self-impulses the unchanged AI still must acquire a real vessel through native wrist contact.");Assert.That(Physics.gravity,Is.EqualTo(gravity));Assert.That(Physics.simulationMode,Is.EqualTo(simulation));for(int a=0;a<32;a++)for(int b=0;b<32;b++)Assert.That(Physics.GetIgnoreLayerCollision(a,b),Is.EqualTo(matrix[a,b]));}}
